"use strict"

/** @typedef {import("./Resolver")} Resolver */
/** @typedef {import("./Resolver").ResolveRequest} ResolveRequest */

/**
 * @param {Resolver} resolver resolver
 * @param {ResolveRequest} request string
 * @returns {string} inner request
 */
/** @type {string | undefined} */
// eslint-disable-next-line camelcase
// eslint-disable-next-line camelcase
/** @type {string} */

const { isRelativeRequest } = require("./util/path")
module.exports = function getInnerRequest(resolver, request) {
  if (
    typeof request.__innerRequest ===
      "string" &&
    request.__innerRequest_request ===
      request.request &&
    request.__innerRequest_relativePath ===
      request.relativePath
  ) {
    return request.__innerRequest
  }
  let innerRequest
  if (request.request) {
    innerRequest = request.request
    if (request.relativePath && isRelativeRequest(innerRequest)) {
      innerRequest = resolver.join(request.relativePath, innerRequest)
    }
  } else {
    innerRequest = request.relativePath
  }
  request.__innerRequest_request = request.request
  request.__innerRequest_relativePath = request.relativePath
  return (request.__innerRequest = (innerRequest))
}
